// 흑백의 집 — 멀티플레이 서버 (외부 패키지 없음: Node 18+ 만 있으면 됨)
// - 게임 화면이 이 파일 안에 들어 있어서 server.js 하나만 올리면 됨
// - /ws 웹소켓: 로그인(닉네임+비밀번호), 접속자 위치·파티 상태 실시간 공유
'use strict';
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const PORT = process.env.PORT || 3000;
const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
const ACC_FILE = path.join(DATA_DIR, 'accounts.json');

// ---------------- 계정 저장소 ----------------
// UPSTASH_REDIS_REST_URL / UPSTASH_REDIS_REST_TOKEN 이 있으면 Upstash Redis(무료, 영구)에 저장.
// 없으면 data/accounts.json 파일에 저장 (Render 무료 플랜에서는 서버가 다시 켜질 때 사라짐).
const REDIS_URL = (process.env.UPSTASH_REDIS_REST_URL || '').replace(/\/+$/, '');
const REDIS_TOKEN = process.env.UPSTASH_REDIS_REST_TOKEN || '';
const STORE = REDIS_URL && REDIS_TOKEN ? 'redis' : 'file';
async function redis(cmd) {
  const res = await fetch(REDIS_URL, { method: 'POST', headers: { Authorization: 'Bearer ' + REDIS_TOKEN, 'Content-Type': 'application/json' }, body: JSON.stringify(cmd) });
  const j = await res.json().catch(() => ({}));
  if (!res.ok || j.error) throw new Error(j.error || ('redis http ' + res.status));
  return j.result;
}
let fileAccounts = {};
if (STORE === 'file') { try { fs.mkdirSync(DATA_DIR, { recursive: true }); fileAccounts = JSON.parse(fs.readFileSync(ACC_FILE, 'utf8')); } catch (e) { fileAccounts = {}; } }
let saveTimer = null;
function saveFile() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => { const tmp = ACC_FILE + '.tmp'; fs.writeFile(tmp, JSON.stringify(fileAccounts), err => { if (!err) fs.rename(tmp, ACC_FILE, () => {}); }); }, 500);
}
const accCache = new Map();
async function getAccount(key) {
  if (STORE === 'file') return fileAccounts[key] || null;
  if (accCache.has(key)) return accCache.get(key);
  const v = await redis(['GET', 'hb:acc:' + key]);
  const acc = v ? JSON.parse(v) : null; if (acc) accCache.set(key, acc); return acc;
}
async function createAccount(key, acc) { // false = someone just took this nickname
  if (STORE === 'file') { if (fileAccounts[key]) return false; fileAccounts[key] = acc; saveFile(); return true; }
  const r = await redis(['SET', 'hb:acc:' + key, JSON.stringify(acc), 'NX']);
  if (r !== 'OK') return false; accCache.set(key, acc); return true;
}
// 재접속 토큰: 서버가 재시작돼도 통하도록 서명해서 만듦 (Render 환경 변수 SECRET 권장)
const SECRET = process.env.SECRET || 'heukbaek-house-change-me';
function makeToken(nick) { const b = Buffer.from(nick, 'utf8').toString('base64url'); return b + '.' + crypto.createHmac('sha256', SECRET).update(b).digest('base64url').slice(0, 32); }
function readToken(tok) { const [b, sig] = String(tok || '').split('.'); if (!b || !sig) return null; const want = crypto.createHmac('sha256', SECRET).update(b).digest('base64url').slice(0, 32); if (sig.length !== want.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(want))) return null; const nick = cleanStr(Buffer.from(b, 'base64url').toString('utf8'), 10); return nick.length >= 2 ? nick : null; }

function cleanStr(v, max) { return String(v == null ? '' : v).replace(/[\u0000-\u001f\u007f​-‏‪-‮⁠-⁯﻿]/g, '').trim().slice(0, max); }
function hashPw(pw, salt) { return crypto.scryptSync(pw, salt, 32, { N: 16384, r: 8, p: 1 }).toString('hex'); }

async function login(conn, nickRaw, pwRaw) {
  const now = Date.now();
  conn.tries = (conn.tries || []).filter(t => now - t < 60000);
  if (conn.tries.length >= 8) return { ok: false, err: '잠시 후 다시 시도하세요' };
  conn.tries.push(now);
  const nick = cleanStr(nickRaw, 10);
  const pw = String(pwRaw == null ? '' : pwRaw).slice(0, 64);
  if (nick.length < 2) return { ok: false, err: '닉네임을 입력하세요' };
  if (pw.length < 4) return { ok: false, err: '비밀번호를 4자 이상 입력하세요' };
  const key = Buffer.from(nick.toLowerCase(), 'utf8').toString('hex');
  let created = false, acc;
  try {
    acc = await getAccount(key);
    if (!acc) {
      const salt = crypto.randomBytes(16).toString('hex');
      const fresh = { nick, salt, hash: hashPw(pw, salt), created: now };
      if (await createAccount(key, fresh)) { acc = fresh; created = true; } else acc = await getAccount(key);
    }
  } catch (e) { console.error('계정 저장소 오류:', e.message); return { ok: false, err: '계정 서버에 연결하지 못했어요. 잠시 후 다시 시도하세요' }; }
  if (!created) {
    const h = Buffer.from(hashPw(pw, acc.salt), 'hex'), want = Buffer.from(acc.hash, 'hex');
    if (h.length !== want.length || !crypto.timingSafeEqual(h, want)) return { ok: false, err: '비밀번호가 틀렸어요' };
  }
  conn.nick = acc.nick;
  conn.presence.nick = conn.nick; dirty = true;
  return { ok: true, created, token: makeToken(conn.nick), nick: conn.nick, store: STORE };
}

// ---------------- 접속자 / 프레즌스 ----------------
const conns = new Map(); // peer -> conn
let dirty = false;
const PRES_KEYS = { where: 'str', rid: 'str', rname: 'str', rd: 'num', priv: 'bool', host: 'bool', phase: 'str', x: 'num', y: 'num',
  hid: 'bool', fl: 'bool', nv: 'bool', sp: 'bool', mv: 'bool', esc: 'bool', mx: 'num', my: 'num', ms: 'str', mf: 'bool', kall: 'long', ws: 'long', hw: 'str' };
function applyPresence(conn, patch) {
  if (!patch || typeof patch !== 'object') return;
  for (const k of Object.keys(patch)) {
    const type = PRES_KEYS[k]; if (!type) continue;
    const v = patch[k];
    if (v === null) { delete conn.presence[k]; continue; }
    if (type === 'str' && typeof v === 'string') conn.presence[k] = cleanStr(v, 24);
    else if (type === 'long' && typeof v === 'string') conn.presence[k] = cleanStr(v, 400);
    else if (type === 'num' && typeof v === 'number' && Number.isFinite(v) && Math.abs(v) < 1e7) conn.presence[k] = Math.round(v * 100) / 100;
    else if (type === 'bool' && typeof v === 'boolean') conn.presence[k] = v;
  }
  conn.presence.nick = conn.nick || null; // 닉네임은 로그인한 계정 것만
  dirty = true;
}
setInterval(() => {
  if (!dirty) return; dirty = false;
  const peers = [];
  for (const c of conns.values()) peers.push({ peer: c.peer, presence: c.presence });
  const msg = JSON.stringify({ t: 'peers', peers });
  for (const c of conns.values()) c.send(msg);
}, 100);

function onMessage(conn, text) {
  let m; try { m = JSON.parse(text); } catch (e) { return; }
  if (!m || typeof m !== 'object') return;
  if (m.t === 'presence') applyPresence(conn, m.patch);
  else if (m.t === 'login') login(conn, m.nick, m.pw).then(r => conn.send(JSON.stringify(Object.assign({ t: 'login' }, r))));
  else if (m.t === 'resume') {
    const nick = readToken(m.token);
    if (nick) { conn.nick = nick; conn.presence.nick = nick; dirty = true; }
    conn.send(JSON.stringify({ t: 'resume', ok: !!nick, nick: nick || null }));
  }
}

// ---------------- 최소 웹소켓 구현 (RFC 6455) ----------------
const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';
const MAX_PAYLOAD = 64 * 1024;
let nextId = 1;
function wsConnection(socket) {
  const conn = { peer: 'p' + (nextId++).toString(36) + crypto.randomBytes(3).toString('hex'), presence: {}, nick: null, alive: true, buf: Buffer.alloc(0), frags: [] };
  conn.send = (text) => {
    if (socket.destroyed) return;
    const data = Buffer.from(text, 'utf8'); const len = data.length;
    let head;
    if (len < 126) { head = Buffer.from([0x81, len]); }
    else if (len < 65536) { head = Buffer.alloc(4); head[0] = 0x81; head[1] = 126; head.writeUInt16BE(len, 2); }
    else { head = Buffer.alloc(10); head[0] = 0x81; head[1] = 127; head.writeBigUInt64BE(BigInt(len), 2); }
    socket.write(Buffer.concat([head, data]));
  };
  const ctrl = (op, payload = Buffer.alloc(0)) => { if (!socket.destroyed) socket.write(Buffer.concat([Buffer.from([0x80 | op, payload.length]), payload])); };
  conn.ping = () => ctrl(0x9);
  const close = () => { if (conns.delete(conn.peer)) dirty = true; socket.destroy(); };
  socket.on('data', chunk => {
    conn.buf = Buffer.concat([conn.buf, chunk]);
    while (conn.buf.length >= 2) {
      const b0 = conn.buf[0], b1 = conn.buf[1];
      const fin = (b0 & 0x80) !== 0, op = b0 & 0x0f, masked = (b1 & 0x80) !== 0;
      let len = b1 & 0x7f, off = 2;
      if (len === 126) { if (conn.buf.length < 4) return; len = conn.buf.readUInt16BE(2); off = 4; }
      else if (len === 127) { if (conn.buf.length < 10) return; const big = conn.buf.readBigUInt64BE(2); if (big > BigInt(MAX_PAYLOAD)) return close(); len = Number(big); off = 10; }
      if (len > MAX_PAYLOAD || !masked) return close();
      if (conn.buf.length < off + 4 + len) return;
      const mask = conn.buf.slice(off, off + 4); off += 4;
      const payload = Buffer.alloc(len);
      for (let i = 0; i < len; i++) payload[i] = conn.buf[off + i] ^ mask[i & 3];
      conn.buf = conn.buf.slice(off + len);
      if (op === 0x8) { ctrl(0x8); return close(); }
      if (op === 0x9) { ctrl(0xA, payload.slice(0, 125)); continue; }
      if (op === 0xA) { conn.alive = true; continue; }
      if (op === 0x1 || op === 0x0) {
        conn.frags.push(payload);
        if (conn.frags.reduce((a, p) => a + p.length, 0) > MAX_PAYLOAD) return close();
        if (fin) { const text = Buffer.concat(conn.frags).toString('utf8'); conn.frags = []; onMessage(conn, text); }
      }
    }
  });
  socket.on('close', close); socket.on('end', close); socket.on('error', close);
  conns.set(conn.peer, conn); dirty = true;
  conn.send(JSON.stringify({ t: 'welcome', peer: conn.peer, store: STORE }));
  return conn;
}
setInterval(() => {
  for (const c of conns.values()) { if (!c.alive) { c.send = () => {}; conns.delete(c.peer); dirty = true; continue; } c.alive = false; c.ping(); }
}, 25000);

// ---------------- HTTP ----------------
const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml', '.ico': 'image/x-icon' };
// 게임 화면은 이 파일 맨 아래에 압축해서 들어 있음 (다른 html 파일이 필요 없음)
let GAME_HTML=null;
function gamePage(){ if(!GAME_HTML) GAME_HTML=require('zlib').gunzipSync(Buffer.from(GAME_GZ_B64,'base64')); return GAME_HTML; }
const server = http.createServer((req, res) => {
  const url = (req.url || '/').split('?')[0];
  if (url === '/health') { res.writeHead(200, { 'content-type': 'text/plain' }); return res.end('ok ' + conns.size + ' ' + STORE); }
  if (url === '/icon-192.png' || url === '/icon-512.png' || url === '/favicon.ico') {
    res.writeHead(200, { 'content-type': 'image/png', 'cache-control': 'public, max-age=86400' });
    return res.end(Buffer.from(url === '/icon-512.png' ? ICON_512 : ICON_192, 'base64'));
  }
  if (url === '/manifest.json') {
    res.writeHead(200, { 'content-type': 'application/manifest+json; charset=utf-8' });
    return res.end(JSON.stringify({ name: '흑백의 집', short_name: '흑백의 집', start_url: '/', scope: '/', display: 'fullscreen', orientation: 'landscape',
      background_color: '#000000', theme_color: '#000000',
      icons: [{ src: '/icon-192.png', sizes: '192x192', type: 'image/png' }, { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' }] }));
  }
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' });
  res.end(gamePage());
});
server.on('upgrade', (req, socket) => {
  const key = req.headers['sec-websocket-key'];
  if ((req.url || '').split('?')[0] !== '/ws' || !key || (req.headers.upgrade || '').toLowerCase() !== 'websocket') { socket.destroy(); return; }
  const accept = crypto.createHash('sha1').update(key + GUID).digest('base64');
  socket.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ' + accept + '\r\n\r\n');
  socket.setNoDelay(true);
  wsConnection(socket);
});
server.listen(PORT, () => {
  console.log('흑백의 집 서버 실행 중: http://localhost:' + PORT);
  console.log('계정 저장: ' + (STORE === 'redis' ? 'Upstash Redis (영구 저장)' : '파일 data/accounts.json (Render 무료 플랜에서는 재시작 시 초기화)'));
  console.log('게임 화면 준비됨 (' + gamePage().length + ' bytes)');
});

// ---------------- 게임 화면 (gzip + base64) ----------------
const GAME_GZ_B64 = '';
const ICON_192 = '';
const ICON_512 = '';
